// Source of truth for the Synthacon ProductDemo props: props/synthacon-demo.json is
// GENERATED by this script — edit copy HERE, never in the JSON (it gets clobbered).
//
// The captured footage facts (video path + telemetry) come from the recorder's raw
// output props/synthacon-demo.capture.json (feeders/capture/record-synthacon-demo.mjs);
// this builder overlays the brand copy (brandId + cta) on top, so the recorder never
// has to know the brand voice and the JSON the studio consumes has one writer.
//
// If out/synthacon/marketing/brief.json exists and validates, its `cta` overrides the
// hardcoded CTA below (same Content-Brief overlay convention as build-launch-props.mjs);
// the footage/telemetry structure always stays local. With no valid brief the output is
// the hardcoded copy.
import {readFileSync, existsSync, writeFileSync} from 'node:fs';
import {fileURLToPath} from 'node:url';
import {dirname, join} from 'node:path';

const root = join(dirname(fileURLToPath(import.meta.url)), '..');

const capturePath = join(root, 'props', 'synthacon-demo.capture.json');
if (!existsSync(capturePath)) {
  console.error(
    'build-synthacon-demo-props: props/synthacon-demo.capture.json missing — run the recorder first:\n' +
      '  cd feeders/capture && SYN_WEB=http://localhost:5173 node record-synthacon-demo.mjs',
  );
  process.exit(1);
}
const capture = validCapture(readFileSync(capturePath, 'utf8'));
if (!capture) {
  console.error('build-synthacon-demo-props: props/synthacon-demo.capture.json is malformed (expected {video, telemetry}).');
  process.exit(1);
}

// Brand voice: CTA is "Join the beta" (open beta), url synthacon.com. Middot separator,
// never an em dash (public-copy rule). Kept lint-copy clean.
const demo = {
  brandId: 'synthacon',
  video: capture.video,
  cta: 'Join the beta · synthacon.com',
  telemetry: capture.telemetry,
};

// Overlay the Content Brief CTA when a valid brief exists (mirrors build-launch-props;
// only the copy field this builder owns is read). A missing/malformed brief falls
// through to the hardcoded CTA untouched.
const briefPath = join(root, 'out', 'synthacon', 'marketing', 'brief.json');
if (existsSync(briefPath)) {
  const brief = validBrief(readFileSync(briefPath, 'utf8'));
  if (!brief) {
    console.warn('build-synthacon-demo-props: out/synthacon/marketing/brief.json is invalid; using hardcoded CTA');
  } else if (brief.cta) {
    demo.cta = brief.cta;
  }
}

writeFileSync(join(root, 'props', 'synthacon-demo.json'), JSON.stringify(demo, null, 2) + '\n');
console.log('wrote props/synthacon-demo.json');

// Returns {video, telemetry} if the capture file structurally matches what ProductDemo
// consumes (telemetrySchema shape), else null. Mirrors the studio's telemetry zod schema
// (studio/src/lib/telemetry.ts) — same convention build-launch-props uses for briefs.
function validCapture(text) {
  let c;
  try {
    c = JSON.parse(text);
  } catch {
    return null;
  }
  if (!c || typeof c !== 'object') return null;
  if (typeof c.video !== 'string' || c.video.length === 0) return null;
  const t = c.telemetry;
  if (!t || typeof t !== 'object') return null;
  if (!t.viewport || typeof t.viewport.width !== 'number' || typeof t.viewport.height !== 'number') return null;
  if (typeof t.durationMs !== 'number' || t.durationMs <= 0) return null;
  if (!Array.isArray(t.events)) return null;
  for (const e of t.events) {
    if (!e || typeof e.type !== 'string' || typeof e.t !== 'number') return null;
  }
  return {video: c.video, telemetry: t};
}

// Returns the parsed brief's cta if it structurally matches brief.ts's copy fields,
// else null (only the field this builder consumes is validated).
function validBrief(text) {
  let b;
  try {
    b = JSON.parse(text);
  } catch {
    return null;
  }
  if (!b || typeof b !== 'object') return null;
  if (typeof b.brandId !== 'string' || b.brandId.length === 0) return null;
  if (b.cta != null && typeof b.cta !== 'string') return null;
  return {cta: typeof b.cta === 'string' ? b.cta : ''};
}
